// ── Derived helpers ─────────────────────────────────────────────────────────

export interface SupplierRollup { supplier: Supplier; servesAnchors: string[]; sectors: string[]; }

export function supplierRollup(): SupplierRollup[] {
  const byKey = new Map<string, SupplierRollup>();
  for (const sector of AI_TECH_INTEL) {
    for (const anchor of sector.anchors) {
      for (const s of anchor.suppliers) {
        const key = s.listed && s.ticker ? s.ticker : s.name;
        const existing = byKey.get(key);
        if (existing) {
          if (!existing.servesAnchors.includes(anchor.anchor)) existing.servesAnchors.push(anchor.anchor);
          if (!existing.sectors.includes(sector.name)) existing.sectors.push(sector.name);
        } else {
          byKey.set(key, { supplier: s, servesAnchors: [anchor.anchor], sectors: [sector.name] });
        }
      }
    }
  }
  return [...byKey.values()];
}

export function intelCounts() {
  const sectors = AI_TECH_INTEL.length;
  const anchors = AI_TECH_INTEL.reduce((n, s) => n + s.anchors.length, 0);
  const rollup = supplierRollup();
  const suppliers = rollup.length;
  const listed = rollup.filter((r) => r.supplier.listed).length;
  const deals = AI_TECH_INTEL.reduce(
    (n, s) => n + s.anchors.reduce((m, a) => m + a.suppliers.filter((x) => x.deal).length, 0),
    0,
  );
  return { sectors, anchors, suppliers, listed, deals };
}
